import { useRef } from 'react';
import { FabricText, Group, Rect } from 'fabric';
import type { ImageEditorController, ShapeDefinition } from 'fabri-pix';

import {
	Callout,
	CodeBlock,
	Demo,
	DemoButton,
	DemoControls,
	DemoEditor,
	DemoLog,
	DocLink,
	H2,
	H3,
	PageHeader,
	PropTable,
	useLog,
} from '../../ui';

const badgeShape: ShapeDefinition = {
	type: 'badge',
	// shown in the history panel: "Badge Created"
	label: 'Badge',
	// called by editor.addShape('badge', data), data.id is generated by the editor
	create: (data, { canvas }) => {
		const { id, text = 'NEW', color = '#2563eb', left = 40, top = 40 } = data;
		const label = new FabricText(text, {
			fontSize: 18,
			fontWeight: 'bold',
			fill: '#ffffff',
			originX: 'center',
			originY: 'center',
		});
		const pill = new Rect({
			width: label.width + 28,
			height: 34,
			rx: 17,
			ry: 17,
			fill: color,
			originX: 'center',
			originY: 'center',
		});
		const badge = new Group([pill, label], { left, top });
		badge.set({ id, shapeType: 'badge' });
		canvas.add(badge);
		canvas.setActiveObject(badge);
	},
	// no `restore`: undo / redo / initialState use Fabric's own deserialization of the Group
};

const shapes = [badgeShape];

const badgeCode = `import { FabricText, Group, Rect } from 'fabric';
import { ImageEditor, type ImageEditorController, type ShapeDefinition } from 'fabri-pix';

const badgeShape: ShapeDefinition = {
  type: 'badge',
  // shown in the history panel: "Badge Created"
  label: 'Badge',
  // called by editor.addShape('badge', data), data.id is generated by the editor
  create: (data, { canvas }) => {
    const { id, text = 'NEW', color = '#2563eb', left = 40, top = 40 } = data;
    const label = new FabricText(text, {
      fontSize: 18, fontWeight: 'bold', fill: '#ffffff', originX: 'center', originY: 'center',
    });
    const pill = new Rect({
      width: label.width + 28, height: 34, rx: 17, ry: 17,
      fill: color, originX: 'center', originY: 'center',
    });
    const badge = new Group([pill, label], { left, top });
    badge.set({ id, shapeType: 'badge' });
    canvas.add(badge);
    canvas.setActiveObject(badge);
  },
  // no \`restore\`: undo / redo / initialState use Fabric's own deserialization of the Group
};

const shapes = [badgeShape];

function Editor() {
  const editor = useRef<ImageEditorController>(null);
  const addBadge = (text: string, color: string) => {
    const { width, height } = editor.current!.getSceneSize();
    void editor.current!.addShape('badge', {
      text,
      color,
      left: 40 + Math.random() * (width - 160),
      top: 40 + Math.random() * (height - 100),
    });
  };
  return (
    <>
      <button onClick={() => addBadge('NEW', '#2563eb')}>Add “NEW”</button>
      <button onClick={() => addBadge('SALE', '#e11d48')}>Add “SALE”</button>
      <button onClick={() => void editor.current?.undo()}>Undo</button>
      <button onClick={() => void editor.current?.redo()}>Redo</button>
      <ImageEditor ref={editor} src={url} shapes={shapes} />
    </>
  );
}`;

function BadgeDemo() {
	const editor = useRef<ImageEditorController>(null);
	const { entries, log, clear } = useLog();

	const addBadge = async (text: string, color: string) => {
		const current = editor.current;
		if (!current?.getState().ready) {
			return;
		}
		const { width, height } = current.getSceneSize();
		await current.addShape('badge', {
			text,
			color,
			left: 40 + Math.random() * (width - 160),
			top: 40 + Math.random() * (height - 100),
		});
		log(`addShape('badge', { text: '${text}' }) → history entries: ${current.getState().history.entries.length}`);
	};

	const badges = () =>
		editor.current?.canvas?.getObjects().filter((object) => (object as any).shapeType === 'badge').length ?? 0;

	return (
		<>
			<DemoControls>
				<DemoButton onClick={() => void addBadge('NEW', '#2563eb')}>Add “NEW”</DemoButton>
				<DemoButton onClick={() => void addBadge('SALE', '#e11d48')}>Add “SALE”</DemoButton>
				<DemoButton
					onClick={async () => {
						await editor.current?.undo();
						log(`undo → badges on the canvas: ${badges()}`);
					}}
				>
					Undo
				</DemoButton>
				<DemoButton
					onClick={async () => {
						await editor.current?.redo();
						log(`redo → badges on the canvas: ${badges()}`);
					}}
				>
					Redo
				</DemoButton>
			</DemoControls>
			<DemoEditor ref={editor} height={420} shapes={shapes} />
			<DemoLog entries={entries} onClear={clear} placeholder='Add a badge, then undo and redo' />
		</>
	);
}

export default function CustomShapesPage() {
	return (
		<>
			<PageHeader
				eyebrow='Extending'
				title='Custom shapes'
				lead='A shape definition tells the editor how objects of one shapeType are created, restored from JSON, deleted and recorded in the history.'
			/>

			<H2 id='when'>When do you need one?</H2>
			<p>
				Every object on the canvas has a <code>shapeType</code> property (<code>&apos;rectangle&apos;</code>,{' '}
				<code>&apos;text&apos;</code>, <code>&apos;blur&apos;</code>…). The editor looks up the{' '}
				<code>ShapeDefinition</code> with that type whenever it needs to know something about the object.
				Objects without a definition still work: they are recorded on every change and restored with Fabric’s
				own deserialization. Add a definition when you want to:
			</p>
			<ul>
				<li>
					create objects from code with{' '}
					<DocLink to='api/objects#addshape'>
						<code>editor.addShape(type, data)</code>
					</DocLink>
					;
				</li>
				<li>
					re-create them in a special way on undo, redo and initialState (custom classes, images, extra
					setup);
				</li>
				<li>delete several objects together (an object and its label, an arrow and its head);</li>
				<li>control when a history entry is recorded, e.g. only once a drag is finished;</li>
				<li>give the object a readable name in the history panel.</li>
			</ul>

			<H2 id='example'>Example: a badge</H2>
			<p>
				The badge is a Fabric.js <code>Group</code> of a rounded rectangle and a text. Register the definition
				through the <code>shapes</code> prop and add badges with <code>editor.addShape</code>.
			</p>
			<Demo
				title='Badges created with addShape, surviving undo and redo'
				description={
					<p>
						Add a few badges and move them around, then undo and redo. Open the history (clock icon in the
						header): the entries say “Badge Created”.
					</p>
				}
				code={badgeCode}
			>
				<BadgeDemo />
			</Demo>

			<H2 id='shape-definition'>ShapeDefinition reference</H2>
			<CodeBlock
				lang='ts'
				code={`interface ShapeDefinition {
  type: string;
  label?: string;
  create?: (data: any, context: ShapeContext) => void | Promise<void>;
  restore?: (data: any, context: ShapeContext) => void | Promise<void>;
  getRelatedObjects?: (object: FabricObject, canvas: Canvas) => FabricObject[];
  helper?: boolean;
  recordModifications?: boolean;
  transient?: boolean;
  recordOnAdd?: boolean;
}

interface ShapeContext {
  editor: ImageEditorController;
  canvas: Canvas;
}`}
			/>
			<PropTable
				nameLabel='Property'
				rows={[
					{
						name: 'type',
						type: 'string',
						required: true,
						description: (
							<p>
								The <code>shapeType</code> this definition describes. A definition with the type of a
								built-in shape replaces it.
							</p>
						),
					},
					{
						name: 'label',
						type: 'string',
						description: <p>Name in the history panel (“Badge Created”). Defaults to “Annotation”.</p>,
					},
					{
						name: 'create',
						type: '(data, context) => void | Promise',
						description: (
							<p>
								Creates the object and adds it to <code>context.canvas</code>. Called by{' '}
								<code>editor.addShape(type, data)</code>, which passes a new <code>id</code> in{' '}
								<code>data</code> (unless you pass one) and records a history entry when it resolves.
							</p>
						),
					},
					{
						name: 'restore',
						type: '(data, context) => void | Promise',
						description: (
							<p>
								Re-creates an object from its JSON on undo, redo, history jumps,{' '}
								<code>initialState</code>, <code>loadState</code>, paste and duplicate. Must add the
								object to the canvas. Without it, Fabric’s <code>util.enlivenObjects</code> is used.
							</p>
						),
					},
					{
						name: 'getRelatedObjects',
						type: '(object, canvas) => FabricObject[]',
						description: (
							<p>
								Objects that belong to this one: they are deleted together, keep their stacking position
								next to it and get the same opacity through <code>setObjectStyle</code>.
							</p>
						),
					},
					{
						name: 'helper',
						type: 'boolean',
						default: 'false',
						description: (
							<p>
								The object is a part of another one (e.g. an arrow head). Adding, moving or removing it
								does not record a history entry, and it is not selected by Select all.
							</p>
						),
					},
					{
						name: 'recordModifications',
						type: 'boolean',
						default: 'false',
						description: (
							<p>
								For helpers that the user edits directly (e.g. the text in a callout): their
								modifications are recorded.
							</p>
						),
					},
					{
						name: 'transient',
						type: 'boolean',
						default: 'false',
						description: (
							<p>
								Editing UI only (the crop rectangle, previews while drawing): never recorded, removed
								from <code>toJSON()</code> and never part of the exported image.
							</p>
						),
					},
					{
						name: 'recordOnAdd',
						type: 'boolean',
						default: 'true',
						description: (
							<p>
								<code>false</code> when the tool draws the object by dragging and records the entry
								itself with <code>editor.commit()</code> once it is complete (lines, arrows, drawings,
								blur).
							</p>
						),
					},
				]}
			/>

			<H2 id='registering'>Registering a definition</H2>
			<H3 id='shapes-prop'>Through the shapes prop</H3>
			<CodeBlock code={`<ImageEditor src={url} shapes={[badgeShape, pinShape]} />`} />
			<H3 id='register-shape'>At runtime</H3>
			<p>
				<code>editor.registerShape(definition)</code> adds or replaces one, e.g. from a plugin that only has the
				editor instance:
			</p>
			<CodeBlock
				code={`<ImageEditor
  src={url}
  onReady={(editor) => editor.registerShape(badgeShape)}
/>`}
			/>
			<Callout type='warning' title='Register before restoring'>
				<p>
					<code>initialState</code> is restored while the image loads, before <code>onReady</code>. If a saved
					state contains your shape and it needs a custom <code>restore</code>, pass it through the{' '}
					<code>shapes</code> prop.
				</p>
			</Callout>

			<H2 id='how-restore-works'>How undo and restore work</H2>
			<p>
				Every history entry is the JSON of the whole canvas (the photo itself is stored once). On undo, the
				canvas is cleared and every object of the entry is re-created one by one, in stacking order, through its
				definition’s <code>restore</code> (or Fabric’s deserialization). This is why:
			</p>
			<ul>
				<li>
					everything an object needs must be in its JSON. Fabric serializes its own properties plus the
					editor’s custom ones: <code>id</code>, <code>shapeType</code>, <code>lastLeft</code>,{' '}
					<code>lastTop</code>, <code>test</code>, <code>fpFilters</code> and <code>fpResize</code>. Keep
					extra data in those, or in standard Fabric.js properties;
				</li>
				<li>
					object references don’t survive an undo. Find objects again by <code>id</code> instead of keeping
					them in variables;
				</li>
				<li>
					a custom Fabric.js subclass must be registered with Fabric’s <code>classRegistry</code>, or restored
					through your own <code>restore</code>.
				</li>
			</ul>

			<H2 id='related-objects'>Objects made of several parts</H2>
			<p>
				Sometimes one visible thing is several canvas objects, for example a pin with a separate label that is
				not grouped. Give the parts ids derived from the main object, mark the part as a helper and return it
				from <code>getRelatedObjects</code>:
			</p>
			<CodeBlock
				code={`const pinShape: ShapeDefinition = {
  type: 'pin',
  label: 'Pin',
  create: (data, { canvas }) => {
    const pin = new Circle({ left: data.left, top: data.top, radius: 8, fill: '#e11d48' });
    pin.set({ id: data.id, shapeType: 'pin' });
    const label = new FabricText(data.text ?? 'Pin', { left: data.left + 20, top: data.top - 4, fontSize: 16 });
    label.set({ id: \`\${data.id}-label\`, shapeType: 'pin_label' });
    canvas.add(pin, label);
  },
  // deleted together with the pin, kept next to it when the layer order changes
  getRelatedObjects: (object, canvas) =>
    canvas.getObjects().filter((other: any) => other.id === \`\${(object as any).id}-label\`),
};

// the label is a part of the pin: no history entries of its own, except when its text is edited
const pinLabelShape: ShapeDefinition = { type: 'pin_label', helper: true, recordModifications: true };

<ImageEditor src={url} shapes={[pinShape, pinLabelShape]} />`}
			/>

			<H2 id='drawn-shapes'>Shapes that are drawn by dragging</H2>
			<p>
				When a tool adds an object on mouse down and resizes it while the mouse moves, a history entry on add
				would record a zero-sized object. Set <code>recordOnAdd: false</code> and commit when the drag ends:
			</p>
			<CodeBlock
				code={`const boxShape: ShapeDefinition = { type: 'box', label: 'Box', recordOnAdd: false };

const boxTool: ToolDefinition = {
  id: 'box',
  label: 'Box',
  shapeTypes: ['box'],
  activate: (context) => {
    const { canvas, editor } = context;
    let box: Rect | null = null;
    let start = { x: 0, y: 0 };
    context.setSelectionEnabled(false);
    context.on('mouse:down', (event) => {
      if (canvas.findTarget(event.e)) return;
      start = canvas.getScenePoint(event.e);
      box = new Rect({ left: start.x, top: start.y, width: 0, height: 0, fill: 'transparent', stroke: '#2563eb', strokeWidth: 3 });
      box.set({ id: generateId(), shapeType: 'box' });
      canvas.add(box); // not recorded yet
    });
    context.on('mouse:move', (event) => {
      if (!box) return;
      const point = canvas.getScenePoint(event.e);
      box.set({
        left: Math.min(start.x, point.x), top: Math.min(start.y, point.y),
        width: Math.abs(point.x - start.x), height: Math.abs(point.y - start.y),
      });
      canvas.requestRenderAll();
    });
    context.on('mouse:up', () => {
      box?.setCoords();
      box = null;
      editor.commit(); // one entry with the finished box
    });
  },
};

<ImageEditor src={url} tools={['text', boxTool]} shapes={[boxShape]} />`}
			/>

			<H2 id='built-in-shapes'>Built-in shape definitions</H2>
			<p>
				The definitions of the built-in objects are exported as <code>builtInShapes</code>, and their types as{' '}
				<code>ShapeType</code> (see <DocLink to='api/utilities#shape-type'>Constants &amp; utilities</DocLink>).
				The data accepted by <code>addShape</code> for each built-in type is described in{' '}
				<DocLink to='api/objects#addshape'>editor.addShape</DocLink>.
			</p>
		</>
	);
}
